SELECT
  min(latitude) AS min_latitude,
  min(longitude) AS min_longitude,
  max(latitude) AS max_latitude,
  max(longitude) AS max_longitude,
  cast(sum(population) as integer) AS population
FROM yemen_2020
WHERE
  type='total_population'
  AND ST_Within(
    ST_Point(longitude, latitude),
    ST_Polygon('POLYGON ((43.376554 12.6057015,43.3887063 12.8411923,43.65 13.05,44.0 13.2,44.4 13.4,44.75 13.8,45.2 13.9,45.5 13.9,45.9 14.2,46.3 14.7,46.7 15.3,47.0 16.0,47.0465019 16.9994659,47.3922177 17.1596879,47.5594666 17.479826,48.1979818 18.2594461,49.1334253 18.6959141,50.8248067 18.8518234,52.0547421 19.0908003,53.1768052 16.652256,52.4169126 16.3557305,52.1960847 15.9447717,52.2737513 15.5504878,51.902669 15.432391,51.5331335 15.2448855,51.1188451 15.1271198,50.4545268 14.9673151,50.0459001 14.7674472,49.7835219 14.7598344,49.0932188 14.4701083,48.7843081 14.0368276,48.2414763 13.937233,47.9470166 13.9959461,47.6172529 13.789639,47.4524903 13.6053982,46.9229735 13.488822,46.6757854 13.3835517,46.1334878 13.3674183,45.6608773 13.2804926,45.4125208 12.9397946,45.1515183 12.8301321,45.1158901 12.7127006,44.7707449 12.6701048,44.5320362 12.6877051,44.1487064 12.5600602,43.5945925 12.6367311,43.376554 12.6057015))')
  );
